function toggle(a, b, c, d) {
    var e = document.getElementById(a);
    var f = document.getElementById(b);
    var isDisplayed = e.style.display === "block";
    
    if (isDisplayed) {
        e.style.display = "none";
        f.innerHTML = c;
    } else {
        e.style.display = "block";
        f.innerHTML = d;
    }
    
    window.parent.postMessage({ action: 'toggle', isDisplayed: !isDisplayed }, '*');
}